const data = window.PORTFOLIO;
const escapeHTML = (value) => String(value ?? '').replace(/[&<>"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[char]));
const tags = (items) => items.map((item) => `<span class="tag">${escapeHTML(item)}</span>`).join('');

document.querySelector('#core-games').innerHTML = data.coreGames.map((game, index) => `<article class="core-card"><div class="card-top"><span class="eyebrow">${escapeHTML(game.genre)}</span><span class="card-index">0${index + 1}</span></div><h4>${escapeHTML(game.name)}</h4><div class="metric">${escapeHTML(game.metric)}<span>${escapeHTML(game.unit)}</span></div><p class="period">${escapeHTML(game.period)}</p><p class="game-detail">${escapeHTML(game.detail)}</p><p class="game-description">${escapeHTML(game.description)}</p><div class="tags">${tags(game.tags)}</div></article>`).join('');

function renderGames(selector, games) {
  document.querySelector(selector).innerHTML = games.map((game) => `<article class="game-row${game.description ? ' has-description' : ''}"><div><h4>${escapeHTML(game.name)}</h4><p>${escapeHTML(game.genre)}${game.note ? ` <span class="playing">· ${escapeHTML(game.note)}</span>` : ''}</p></div><span class="duration">${escapeHTML(game.duration)}</span>${game.description ? `<p class="experience-note">${escapeHTML(game.description)}</p>` : ''}${game.caseStudy ? `<button class="case-crosslink" type="button" data-open-case="${escapeHTML(game.caseStudy)}">관련 분석 프로젝트 보기 ↗</button>` : ''}</article>`).join('');
}

function renderExperienceGroup(featuredSelector, listSelector, games) {
  document.querySelector(featuredSelector).innerHTML = games.filter((game) => game.featured).map((game) => `<article class="experienced-card"><p>${escapeHTML(game.genre)}</p><h4>${escapeHTML(game.name)}</h4><span class="experience-duration">${escapeHTML(game.duration)}</span>${game.note ? `<p class="playing">${escapeHTML(game.note)}</p>` : ''}${game.description ? `<p class="experience-note">${escapeHTML(game.description)}</p>` : ''}</article>`).join('');
  renderGames(listSelector, games.filter((game) => !game.featured));
}

renderExperienceGroup('#experienced-featured', '#pc-games', data.experiencedGames);
renderExperienceGroup('#mobile-featured', '#mobile-games', data.mobileGames);
document.querySelector('#past-mobile-games').innerHTML = tags(data.pastMobileGames);
document.querySelector('#interest-tags').innerHTML = tags(data.interests);

const statusClasses = { Observation: 'observation', Hypothesis: 'hypothesis', 'Partial Evidence': 'observation', 'Analysis in Progress': 'progress', 'Data to be Added': 'pending', 'Verified Result': 'verified', 'Case Study Complete': 'verified', 'Operations Plan Complete': 'verified', 'Public Evidence Audit': 'verified', 'Personal Journey Study': 'observation', 'Project Preparing': 'pending' };
const statusLabels = { Observation: '개인 관찰', Hypothesis: '미검증 가설', 'Partial Evidence': '화면 확인 · 이용 주체 자기 보고', 'Analysis in Progress': '분석 진행 중', 'Data to be Added': '자료 준비 중', 'Verified Result': '자료 확인', 'Case Study Complete': '사례 분석 완료', 'Operations Plan Complete': '운영안 설계 완료', 'Public Evidence Audit': '공개자료 감사 완료', 'Personal Journey Study': '1인 사용자 여정', 'Project Preparing': '프로젝트 준비 중' };
const stepLabels = { 'Personal Experience': '직접 경험', Observation: '관찰', Question: '핵심 질문', Hypothesis: '가설', 'Data to Verify': '검증할 자료', Analysis: '분석', Insight: '인사이트', Proposal: '개선 제안', 'Expected Effect': '기대 효과', 'Risk / Trade-off': '위험 및 고려사항', Limitation: '분석 한계', 'What I Learned': '배운 점' };
const artifactLabels = { 'Analysis Document': '분석 문서', 'Excel / Google Sheets': '데이터 시트', PPT: '발표 자료', Notion: 'Notion 정리', Screenshot: '화면 자료', 'Research Sources': '조사 출처', '심볼 강화 비용 계산표': '심볼 강화 비용 계산표', '출처 대장 CSV': '출처 대장 CSV', '사건 데이터셋 CSV': '사건 데이터셋 CSV', '수집 방법': '수집 방법', '발견 보고서': '발견 보고서' };
const badge = (status) => `<span class="status ${statusClasses[status] || 'pending'}">${escapeHTML(statusLabels[status] || status)}</span>`;
const assetURL = (url) => typeof url === 'string' && (/^https:\/\//i.test(url) || /^(?:\.\/)?(?:assets|research)\/[a-zA-Z0-9_./% -]+$/.test(url)) ? url : '';
function artifactLinks(items) {
  return items.filter((item) => assetURL(item.url)).map((item) => {
    const url = assetURL(item.url);
    const label = artifactLabels[item.label] || item.label;
    return `<a class="artifact" href="${escapeHTML(url)}" target="_blank" rel="noopener noreferrer">${escapeHTML(label)} ↗</a>`;
  }).join('');
}

const visibleCaseStudies = data.caseStudies.filter((study) => study.visible !== false);
const featuredCaseIds = new Set(['maple-idle']);
const featuredCaseStudies = visibleCaseStudies.filter((study) => featuredCaseIds.has(study.id));
const secondaryCaseStudies = visibleCaseStudies.filter((study) => !featuredCaseIds.has(study.id));
const renderCaseCards = (studies) => studies.map((study) => {
  const index = visibleCaseStudies.indexOf(study);
  const cardMeta = study.cardMeta?.length ? `<div class="case-card-meta">${study.cardMeta.map((item) => `<span>${escapeHTML(item)}</span>`).join('')}</div>` : '';
  const cardFacts = study.cardFacts?.length ? `<ul class="case-card-facts">${study.cardFacts.map((item) => `<li>${escapeHTML(item)}</li>`).join('')}</ul>` : '';
  const featuredClass = featuredCaseIds.has(study.id) ? ' featured-case-card' : '';
  return `<article class="case-card${featuredClass}"><div class="case-folder" aria-hidden="true"></div><div class="case-card-top"><span>0${index + 1}</span>${badge(study.status)}</div><div class="case-card-copy"><p class="case-game">${escapeHTML(study.game)}</p><h3>${escapeHTML(study.title)}</h3>${cardMeta}<p>${escapeHTML(study.summary)}</p></div>${cardFacts}<button type="button" class="case-open" data-open-case="${escapeHTML(study.id)}">1분 요약부터 검토하기 <span aria-hidden="true">→</span></button></article>`;
}).join('');
document.querySelector('#case-studies').innerHTML = `<section class="project-tier featured-tier"><div class="project-tier-heading"><span>FEATURED · 대표작</span><p>공개자료의 비교 가능성을 검토하고 경쟁 가설에서 조건부 사업 액션까지 연결합니다.</p></div><div class="case-card-grid">${renderCaseCards(featuredCaseStudies)}</div></section>${secondaryCaseStudies.length ? `<section class="project-tier supporting-tier"><div class="project-tier-heading"><span>SUPPORTING · 보조작</span><p>이벤트 종료 후 한 이용자의 실제 행동과 자기 보고 동기를 분리해 관찰합니다.</p></div><div class="case-card-grid">${renderCaseCards(secondaryCaseStudies)}</div></section>` : ''}`;
const dialog = document.createElement('dialog');
dialog.className = 'case-dialog';
dialog.setAttribute('aria-labelledby', 'case-dialog-title');
document.body.appendChild(dialog);
let lastCaseTrigger = null;

function openCase(id) {
  const study = data.caseStudies.find((item) => item.id === id);
  if (!study) return;
  const index = visibleCaseStudies.indexOf(study);
  const meta = study.meta?.length ? `<dl class="case-meta">${study.meta.map((item) => `<div><dt>${escapeHTML(item.label)}</dt><dd>${escapeHTML(item.value)}</dd></div>`).join('')}</dl>` : '';
  const executiveSummary = study.executiveSummary?.length ? `<section class="executive-summary"><div class="structured-heading"><span class="eyebrow">ONE-MINUTE REVIEW</span><h3>1분 요약</h3></div><div>${study.executiveSummary.map((item) => `<article><span>${escapeHTML(item.label)}</span><h4>${escapeHTML(item.title)}</h4><p>${escapeHTML(item.text)}</p></article>`).join('')}</div></section>` : '';
  const researchFacts = study.researchFacts?.length ? `<section class="structured-section"><div class="structured-heading"><span class="eyebrow">VERIFIED FACTS</span><h3>공개자료로 확인한 사실</h3><p>공식 자료, 외부 추정, 개인 기록을 같은 수준의 근거로 취급하지 않았습니다.</p></div><div class="takeaway-list">${study.researchFacts.map((item, i) => `<article><span>0${i + 1}</span><div><h4>${escapeHTML(item.title)}</h4><p>${escapeHTML(item.text)}</p><small>${escapeHTML(item.source)}</small></div></article>`).join('')}</div></section>` : '';
  const comparability = study.comparability?.length ? `<section class="structured-section"><div class="structured-heading"><span class="eyebrow">COMPARABILITY CHECK</span><h3>비교 가능한 것과 불가능한 것</h3><p>기간·플랫폼·측정 주체가 다른 숫자는 하나의 변화처럼 연결하지 않았습니다.</p></div><div class="competency-grid">${study.comparability.map((item) => `<article><span class="eyebrow">${escapeHTML(item.status)}</span><h4>${escapeHTML(item.title)}</h4><p>${escapeHTML(item.text)}</p></article>`).join('')}</div></section>` : '';
  const competingHypotheses = study.competingHypotheses?.length ? `<section class="structured-section"><div class="structured-heading"><span class="eyebrow">COMPETING HYPOTHESES</span><h3>하나로 단정할 수 없는 설명</h3><p>각 가설의 지지 근거와 반대 근거를 함께 두고 결론의 강도를 제한했습니다.</p></div><div class="problem-grid">${study.competingHypotheses.map((item) => `<article class="problem-card"><span class="problem-rank">${escapeHTML(item.code)}</span><h4>${escapeHTML(item.title)}</h4><dl><div><dt>지지 근거</dt><dd>${escapeHTML(item.support)}</dd></div><div><dt>반대·미확인</dt><dd>${escapeHTML(item.counter)}</dd></div></dl></article>`).join('')}</div></section>` : '';
  const actionOptions = study.actionOptions?.length ? `<details class="supporting-details decision-details"><summary>선택·선행·제외 대안 비교 보기 <span>의사결정 근거</span></summary><div class="supporting-body"><section class="structured-section action-decision"><div class="structured-heading"><span class="eyebrow">ACTION DECISION</span><h3>대안을 비교한 현재 결정</h3><p>선택한 실행, 내부 선행 작업과 이미 진행돼 제외한 대안을 구분했습니다.</p></div><div class="proposal-list">${study.actionOptions.map((item, i) => `<article class="proposal-card${item.decision.startsWith('선택') ? ' selected-action' : ''}"><div class="proposal-title"><span>0${i + 1}</span><div><small>${escapeHTML(item.decision)}</small><h4>${escapeHTML(item.title)}</h4></div></div><p>${escapeHTML(item.text)}</p><p class="action-reason"><strong>현재 결정 이유</strong>${escapeHTML(item.reason)}</p><details class="action-option-details"><summary>대상·지표·비용·위험 보기</summary><dl><div><dt>대상</dt><dd>${escapeHTML(item.target)}</dd></div><div><dt>예상 행동 변화</dt><dd>${escapeHTML(item.behavior)}</dd></div><div><dt>판단 지표</dt><dd>${escapeHTML(item.metric)}</dd></div><div><dt>비용·의존성</dt><dd>${escapeHTML(item.cost)}</dd></div><div><dt>위험</dt><dd>${escapeHTML(item.risk)}</dd></div><div><dt>선택 조건</dt><dd>${escapeHTML(item.condition)}</dd></div></dl></details></article>`).join('')}</div></section></div></details>` : '';
  const selectedActionOutput = study.selectedActionOutput?.length ? `<section class="structured-section action-output"><div class="structured-heading"><span class="eyebrow">ACTION OUTPUT</span><h3>월간 회복 리포트 · 공개자료 표본</h3><p>실제 수치를 만들지 않고, 현재 공개된 약속과 구현을 결과·다음 결정까지 연결한 산출물 예시입니다.</p></div><div class="recovery-report" role="table" aria-label="월간 약속 이행 결과 리포트"><div class="recovery-report-head" role="row"><span>영역</span><span>문제와 약속</span><span>실행</span><span>현재 확인 결과</span><span>다음 결정</span></div>${study.selectedActionOutput.map((item) => `<article role="row"><strong>${escapeHTML(item.area)}</strong><div><b>${escapeHTML(item.problem)}</b><p>${escapeHTML(item.commitment)}</p></div><p>${escapeHTML(item.delivery)}</p><p>${escapeHTML(item.outcome)}</p><p>${escapeHTML(item.next)}</p></article>`).join('')}</div></section>` : '';
  const benchmarks = study.benchmarks?.length ? `<section class="structured-section benchmark-section"><div class="structured-heading"><span class="eyebrow">MARKET BENCHMARK</span><h3>약속 현황판에서 결과 의사결정으로</h3><p>공식 공개 방식만 비교했습니다. 타 서비스의 내부 측정 여부나 실제 신뢰 회복 효과는 판단하지 않습니다.</p></div><div class="benchmark-grid">${study.benchmarks.map((item) => `<article><span>${escapeHTML(item.service)}</span><h4>${escapeHTML(item.model)}</h4><dl><div><dt>확인 강점</dt><dd>${escapeHTML(item.strength)}</dd></div><div><dt>공개자료 공백</dt><dd>${escapeHTML(item.gap)}</dd></div></dl></article>`).join('')}</div><p class="benchmark-decision"><strong>대표작 반영</strong>${escapeHTML(study.benchmarkDecision)}</p></section>` : '';
  const recoveryKpis = study.recoveryKpis?.length ? `<section class="structured-section recovery-section"><div class="structured-heading"><span class="eyebrow">RECOVERY KPI TREE</span><h3>무엇을 회복으로 판단할 것인가</h3><p>매출 하나로 결론 내리지 않고 잔존·이용자 기반·결제 분포·신뢰 위험을 함께 봅니다.</p></div><div class="kpi-tree">${study.recoveryKpis.map((item) => `<article><span>${escapeHTML(item.role)}</span><h4>${escapeHTML(item.title)}</h4><p>${escapeHTML(item.text)}</p><small>${escapeHTML(item.need)}</small></article>`).join('')}</div></section>` : '';
  const recoveryCohorts = study.recoveryCohorts?.length ? `<section class="structured-section"><div class="structured-heading"><span class="eyebrow">COHORT PRIORITY</span><h3>누구에게 먼저 개입할 것인가</h3><p>환불·복귀·재결제 상태를 분리하고 결제 후 빠른 활동 감소군을 우선 확인합니다.</p></div><div class="cohort-grid">${study.recoveryCohorts.map((item) => `<article><span>${escapeHTML(item.code)}</span><h4>${escapeHTML(item.title)}</h4><p><b>판단 질문</b>${escapeHTML(item.question)}</p><p><b>첫 액션</b>${escapeHTML(item.action)}</p></article>`).join('')}</div></section>` : '';
  const operationsPlan = study.operationsPlan?.length ? `<section class="structured-section"><div class="structured-heading"><span class="eyebrow">30-DAY LIVE OPERATIONS</span><h3>30일 실행 순서</h3><p>진단 없이 보상부터 집행하지 않고 측정 기준 → 원인 진단 → 최소 실험 → 다음 결정 순서로 진행합니다.</p></div><div class="operations-timeline">${study.operationsPlan.map((item, i) => `<article><div><span>${String(i + 1).padStart(2, '0')}</span><time>${escapeHTML(item.period)}</time></div><h4>${escapeHTML(item.title)}</h4><p>${escapeHTML(item.action)}</p><dl><div><dt>담당</dt><dd>${escapeHTML(item.owner)}</dd></div><div><dt>산출물</dt><dd>${escapeHTML(item.output)}</dd></div></dl></article>`).join('')}</div></section>` : '';
  const decisionGates = study.decisionGates?.length ? `<section class="structured-section compact-section"><div class="structured-heading"><span class="eyebrow">DECISION GATE</span><h3>결과에 따라 무엇을 결정할 것인가</h3><p>실제 임계값은 내부 기준선이 필요하므로 방향과 비교 조건만 정의했습니다.</p></div><div class="decision-gates">${study.decisionGates.map((item) => `<article><p>${escapeHTML(item.signal)}</p><strong>${escapeHTML(item.decision)}</strong></article>`).join('')}</div></section>` : '';
  const milestones = study.milestones?.length ? `<section class="structured-section"><div class="structured-heading"><span class="eyebrow">PROGRESSION</span><h3>성장과 도전 타임라인</h3><p>확인 가능한 생성일과 업적 날짜를 기준으로 정리했습니다.</p></div><ol class="milestone-list">${study.milestones.map((item) => `<li><time>${escapeHTML(item.date)}</time><div><h4>${escapeHTML(item.title)}</h4><p>${escapeHTML(item.text)}</p></div></li>`).join('')}</ol></section>` : '';
  const journeyLabel = study.id === 'maple-idle' ? 'EVENT TIMELINE' : 'USER JOURNEY';
  const journeyDescription = study.id === 'maple-idle'
    ? '공식 발표, 외부 추정 지표와 개인 행동을 날짜순으로 분리해 정리했습니다.'
    : '본인 인터뷰를 바탕으로 선택이 발생한 지점을 정리했습니다.';
  const playerJourney = study.playerJourney?.length ? `<section class="structured-section"><div class="structured-heading"><span class="eyebrow">${journeyLabel}</span><h3>${escapeHTML(study.journeyTitle || '실제 행동 흐름')}</h3><p>${journeyDescription}</p></div><div class="journey-flow">${study.playerJourney.map((item, i) => `<article><span>${String(i + 1).padStart(2, '0')} · ${escapeHTML(item.stage)}</span><h4>${escapeHTML(item.title)}</h4><p>${escapeHTML(item.text)}</p></article>`).join('')}</div></section>` : '';
  const actualRoutine = study.actualRoutine?.length ? `<section class="structured-section compact-section"><div class="structured-heading"><span class="eyebrow">ACTUAL ROUTINE</span><h3>실제 플레이 우선순위</h3></div><div class="routine-grid">${study.actualRoutine.map((item) => `<article><span>${escapeHTML(item.label)}</span><h4>${escapeHTML(item.title)}</h4><p>${escapeHTML(item.text)}</p></article>`).join('')}</div></section>` : '';
  const quantifiedNotes = study.quantifiedNotes?.length ? `<section class="structured-section compact-section"><div class="structured-heading"><span class="eyebrow">PLAYER DATA</span><h3>${escapeHTML(study.dataTitle || '개인 플레이 수치와 의사결정')}</h3><p>${escapeHTML(study.dataDescription || '공식 평균이 아닌 본인 플레이 기록과 회상 범위입니다.')}</p></div><div class="player-data-table" role="table" aria-label="개인 플레이 근거"><div class="player-data-head" role="row"><span>항목</span><span>확인 내용</span><span>조건</span><span>행동에 미친 영향</span></div>${study.quantifiedNotes.map((item) => `<article role="row"><strong>${escapeHTML(item.topic)}</strong><b>${escapeHTML(item.value)}</b><span>${escapeHTML(item.detail)}</span><p>${escapeHTML(item.meaning)}</p></article>`).join('')}</div></section>` : '';
  const monthlySpend = study.monthlySpend?.length ? (() => { const max = Math.max(...study.monthlySpend.map((item) => item.amount)); return `<section class="structured-section compact-section"><div class="structured-heading"><span class="eyebrow">PURCHASE TIMELINE</span><h3>월별 결제 분포</h3><p>결제가 확인된 달만 표시했으며, 막대 길이는 월 최대 결제액 47,100원을 기준으로 계산했습니다.</p></div><div class="spend-chart" role="img" aria-label="2021년 6월부터 2022년 10월까지 월별 결제 금액 막대그래프">${study.monthlySpend.map((item) => `<div class="spend-row"><time>${escapeHTML(item.month)}</time><div><i style="width:${Math.max(3, Math.round(item.amount / max * 100))}%"></i></div><strong>${escapeHTML(item.amount.toLocaleString('ko-KR'))}원</strong></div>`).join('')}</div></section>`; })() : '';
  const decisionSummary = study.decisionSummary?.length ? `<section class="structured-section"><div class="structured-heading"><span class="eyebrow">BM RECORD</span><h3>유료 상품 이용 기록</h3><p>결제 사실과 구매 동기 해석을 분리했습니다.</p></div><div class="decision-grid">${study.decisionSummary.map((item) => `<article><span>${escapeHTML(item.label)}</span><strong>${escapeHTML(item.value)}</strong><p>${escapeHTML(item.detail)}</p></article>`).join('')}</div></section>` : '';
  const bmInsights = study.bmInsights?.length ? `<section class="structured-section compact-section"><div class="structured-heading"><span class="eyebrow">PURCHASE DECISION</span><h3>패스별 구매 판단</h3><p>구매 내역으로 확인된 사실과 구매자의 자기 보고를 구분했습니다.</p></div><div class="bm-list">${study.bmInsights.map((item) => `<article><h4>${escapeHTML(item.product)}</h4><dl><div><dt>구매 이유</dt><dd>${escapeHTML(item.reason)}</dd></div><div><dt>플레이 변화</dt><dd>${escapeHTML(item.change)}</dd></div></dl><small>${escapeHTML(item.level)}</small></article>`).join('')}</div></section>` : '';
  const takeaways = study.takeaways?.length ? `<section class="structured-section"><div class="structured-heading"><span class="eyebrow">KEY FINDINGS</span><h3>현재 자료에서 확인한 시사점</h3><p>증거가 닿는 범위 안에서만 정리했습니다.</p></div><div class="takeaway-list">${study.takeaways.map((item, i) => `<article><span>0${i + 1}</span><div><h4>${escapeHTML(item.title)}</h4><p>${escapeHTML(item.text)}</p><small>근거 · ${escapeHTML(item.basis)}</small></div></article>`).join('')}</div></section>` : '';
  const competencies = study.competencies?.length ? `<section class="structured-section"><div class="structured-heading"><span class="eyebrow">ROLE FIT</span><h3>이 프로젝트로 보여주는 업무 방식</h3></div><div class="competency-grid">${study.competencies.map((item) => `<article><h4>${escapeHTML(item.title)}</h4><p>${escapeHTML(item.text)}</p></article>`).join('')}</div></section>` : '';
  const validationPlan = study.validationPlan?.length ? `<section class="structured-section"><div class="structured-heading"><span class="eyebrow">NEXT VALIDATION</span><h3>현재 한계와 다음 검증</h3><p>단일 사례와 자기 보고를 실제 서비스 판단으로 확장하기 전에 필요한 작업입니다.</p></div><div class="validation-grid">${study.validationPlan.map((item, i) => `<article><span>0${i + 1}</span><div><h4>${escapeHTML(item.title)}</h4><p>${escapeHTML(item.text)}</p></div></article>`).join('')}</div></section>` : '';
  const problemItems = study.compactSecondary ? study.problems?.slice(0, 1) : study.problems;
  const proposalItems = study.compactSecondary ? study.proposals?.slice(0, 1) : study.proposals;
  const problems = problemItems?.length ? `<section class="structured-section"><div class="structured-heading"><span class="eyebrow">PRIORITY</span><h3>핵심 문제</h3><p>개인 경험과 공식 구조에서 확인한 근거를 기준으로 선정했습니다.</p></div><div class="problem-grid">${problemItems.map((item) => `<article class="problem-card"><span class="problem-rank">${escapeHTML(item.rank)}</span><h4>${escapeHTML(item.title)}</h4><dl><div><dt>근거</dt><dd>${escapeHTML(item.evidence)}</dd></div><div><dt>유저 영향</dt><dd>${escapeHTML(item.impact)}</dd></div><div><dt>근거 수준</dt><dd>${escapeHTML(item.confidence)}</dd></div></dl></article>`).join('')}</div></section>` : '';
  const proposals = proposalItems?.length ? `<section class="structured-section"><div class="structured-heading"><span class="eyebrow">PROPOSAL</span><h3>${study.compactSecondary ? '대표 정착 지원안' : '개선안과 측정 계획'}</h3><p>효과를 단정하지 않고 확인할 지표와 부작용을 함께 제시합니다.</p></div><div class="proposal-list">${proposalItems.map((item, i) => `<article class="proposal-card"><div class="proposal-title"><span>0${i + 1}</span><div><small>${escapeHTML(item.forProblem)}</small><h4>${escapeHTML(item.title)}</h4></div></div><p>${escapeHTML(item.idea)}</p><dl><div><dt>확인 지표</dt><dd>${escapeHTML(item.metrics)}</dd></div><div><dt>고려사항</dt><dd>${escapeHTML(item.risk)}</dd></div></dl></article>`).join('')}</div></section>` : '';
  const prototype = study.prototype ? `<section class="structured-section"><div class="structured-heading"><span class="eyebrow">SERVICE CONCEPT</span><h3>대표 개선안 · 목표 선택에서 추천 결과까지</h3><p>실제 행동에서 확인한 선택 충돌을 바탕으로 만든 2단계 개념 시안입니다.</p></div><div class="concept-steps"><article class="goal-selector"><span>STEP 01 · 목표 선택</span><h4>${escapeHTML(study.prototype.title)}</h4><p>${escapeHTML(study.prototype.description)}</p><div>${study.prototype.goalOptions.map((item) => `<article class="${item.selected ? 'selected' : ''}"><strong>${escapeHTML(item.name)}</strong><p>${escapeHTML(item.description)}</p>${item.selected ? '<b>선택됨</b>' : ''}</article>`).join('')}</div></article><article class="service-concept"><header><span>STEP 02 · 맞춤 추천 결과</span><h4>이번 주 추천 활동</h4><p>${escapeHTML(study.prototype.recommendationReason)}</p></header><div class="concept-goal">${escapeHTML(study.prototype.goal)}</div><div class="activity-list">${study.prototype.activities.map((item) => `<article><div><strong>${escapeHTML(item.name)}</strong><span>${escapeHTML(item.time)}</span></div><p>${escapeHTML(item.reward)}</p><small>${escapeHTML(item.state)}</small><b>${escapeHTML(item.priority)}</b></article>`).join('')}</div><footer>${study.prototype.controls.map((item) => `<span>${escapeHTML(item)}</span>`).join('')}</footer><p class="concept-note">검증 계획 · ${escapeHTML(study.prototype.timing)}</p></article></div></section>` : '';
  const secondaryUxFinding = study.secondaryUxFinding ? `<section class="final-decision"><span class="eyebrow">SECONDARY UX FINDING</span><h3>${escapeHTML(study.secondaryUxFinding.title)}</h3><p>${escapeHTML(study.secondaryUxFinding.observation)}</p><dl><div><dt>현재 판단</dt><dd>${escapeHTML(study.secondaryUxFinding.decision)}</dd></div><div><dt>확인 지표</dt><dd>${escapeHTML(study.secondaryUxFinding.metrics)}</dd></div></dl></section>` : '';
  const recommendationRules = study.recommendationRules?.length ? `<section class="structured-section compact-section"><div class="structured-heading"><span class="eyebrow">RECOMMENDATION LOGIC</span><h3>목표별 추천 기준</h3><p>추천 결과가 임의로 보이지 않도록 우선 활동과 예외 조건을 함께 정의했습니다.</p></div><div class="player-data-table rule-table" role="table" aria-label="목표별 추천 기준"><div class="player-data-head" role="row"><span>선택 목표</span><span>우선 추천</span><span>추천 조건</span><span>예외 처리</span></div>${study.recommendationRules.map((item) => `<article role="row"><strong>${escapeHTML(item.goal)}</strong><b>${escapeHTML(item.primary)}</b><span>${escapeHTML(item.condition)}</span><p>${escapeHTML(item.exception)}</p></article>`).join('')}</div></section>` : '';
  const businessFrameHeading = study.id === 'maple-idle'
    ? '<span class="eyebrow">RECOVERY SCORECARD</span><h3>서비스 회복 판정표</h3><p>매출 반등과 서비스 전체의 회복을 분리해 현재 확인 가능한 범위만 판정했습니다.</p>'
    : study.compactSecondary
      ? '<span class="eyebrow">EVIDENCE BOUNDARY</span><h3>확인 행동과 해석의 경계</h3><p>화면으로 확인한 사실, 이용자의 자기 보고와 현재 판단할 수 없는 내용을 분리했습니다.</p>'
      : '<span class="eyebrow">BUSINESS VIEW</span><h3>유저 행동과 사업 목표의 연결</h3><p>개선 화면의 목적을 기능 설명이 아니라 대상·행동·서비스 가치로 정의했습니다.</p>';
  const businessFrame = study.businessFrame?.length ? `<section class="structured-section"><div class="structured-heading">${businessFrameHeading}</div><div class="competency-grid">${study.businessFrame.map((item) => `<article><span class="eyebrow">${escapeHTML(item.label)}</span><h4>${escapeHTML(item.title)}</h4><p>${escapeHTML(item.text)}</p></article>`).join('')}</div></section>` : '';
  const mvpPlan = study.mvpPlan ? `<section class="final-decision mvp-decision"><span class="eyebrow">MVP PRIORITY</span><h3>${escapeHTML(study.mvpPlan.title || '보상 변경 없이 정보 구조부터 검증합니다')}</h3><p>${escapeHTML(study.mvpPlan.scope)}</p><dl><div><dt>우선 적용 이유</dt><dd>${escapeHTML(study.mvpPlan.why)}</dd></div><div><dt>핵심 지표</dt><dd>${escapeHTML(study.mvpPlan.primaryMetric)}</dd></div><div><dt>보조 지표</dt><dd>${escapeHTML(study.mvpPlan.secondaryMetrics)}</dd></div><div><dt>안전 지표</dt><dd>${escapeHTML(study.mvpPlan.guardrails)}</dd></div></dl></section>` : '';
  const finalMetricLabel = study.compactSecondary ? '추가 확인' : '성공 지표';
  const finalDecision = study.finalDecision ? `<section class="final-decision"><span class="eyebrow">FINAL DECISION</span><h3>${escapeHTML(study.finalDecision.title)}</h3><p>${escapeHTML(study.finalDecision.text)}</p><dl><div><dt>${finalMetricLabel}</dt><dd>${escapeHTML(study.finalDecision.metrics)}</dd></div><div><dt>판단 범위</dt><dd>${escapeHTML(study.finalDecision.boundary)}</dd></div></dl></section>` : '';
  const interviewPitch = study.interviewPitch ? `<details class="pitch-details"><summary>면접용 1분 설명 보기 <span>발표문</span></summary><p>${escapeHTML(study.interviewPitch)}</p></details>` : '';
  const evidenceImages = study.evidenceImages?.length ? `<div class="evidence-gallery">${study.evidenceImages.map((item) => `<figure><img src="${escapeHTML(assetURL(item.src))}" alt="${escapeHTML(item.alt)}" loading="lazy"><figcaption>${escapeHTML(item.caption)}</figcaption></figure>`).join('')}</div>` : '';
  const process = `<details class="process-details"><summary>전체 분석 과정 보기 <span>${study.steps.length}단계</span></summary><div class="case-steps">${study.steps.map((step, i) => `<section class="case-step"><div class="step-heading"><h3><span>${String(i + 1).padStart(2, '0')}</span> ${escapeHTML(stepLabels[step.label] || step.label)}</h3>${badge(step.status)}</div><p>${escapeHTML(step.text)}</p></section>`).join('')}</div></details>`;
  const evidence = `<div class="evidence"><h3>근거 자료와 산출물</h3><p>직접 플레이 근거와 확인된 공식 자료를 우선 연결합니다.</p>${evidenceImages}<div class="artifact-grid">${artifactLinks(study.artifacts)}</div></div>`;
  const actionDetails = !study.compactSecondary && (problems || proposals || mvpPlan) ? `<details class="supporting-details action-details"><summary>문제 우선순위와 개선안 보기 <span>제안·측정</span></summary><div class="supporting-body">${problems}${proposals}${mvpPlan}</div></details>` : '';
  const detailedBody = study.compactSecondary
    ? `${meta}<div class="case-highlights"><div>${badge('Observation')}<p>${escapeHTML(study.observation)}</p></div><div>${badge('Hypothesis')}<p>${escapeHTML(study.hypothesis)}</p></div></div>${playerJourney}${quantifiedNotes}${takeaways}${businessFrame}${validationPlan}${evidence}`
    : `${meta}<div class="case-highlights"><div>${badge('Observation')}<p>${escapeHTML(study.observation)}</p></div><div>${badge(study.status === 'Project Preparing' ? 'Data to be Added' : 'Hypothesis')}<p>${escapeHTML(study.hypothesis)}</p></div></div>${study.loop ? `<div class="loop" aria-label="검토 중인 플레이 흐름">${study.loop.map(escapeHTML).join(' <span aria-hidden="true">→</span> ')}</div>` : ''}${milestones}${playerJourney}${actualRoutine}${quantifiedNotes}${monthlySpend}${decisionSummary}${bmInsights}${takeaways}${businessFrame}${prototype}${secondaryUxFinding}${recommendationRules}${competencies}${validationPlan}${process}${evidence}`;
  const supportingDetails = `<details class="supporting-details"><summary>근거·행동 흐름·검증 계획 보기 <span>상세 자료</span></summary><div class="supporting-body">${detailedBody}</div></details>`;
  const researchDetails = researchFacts || comparability || competingHypotheses ? `<details class="supporting-details research-details"><summary>확인 사실·비교 기준·경쟁 가설 보기 <span>근거 분석</span></summary><div class="supporting-body">${researchFacts}${comparability}${competingHypotheses}</div></details>` : '';
  const reviewRoute = study.id === 'maple-idle'
    ? ['1분 요약', '선택 액션', '리포트 표본', '시장 비교']
    : study.compactSecondary
      ? ['1인 여정', '확인 행동', '자기 보고 동기', '검증 한계']
      : ['1분 요약', '핵심 문제', '개선안', '판단 기준'];
  dialog.innerHTML = `<div class="dialog-shell"><button class="dialog-close" type="button" aria-label="프로젝트 상세 닫기">×</button><div class="case-top"><p class="eyebrow">PROJECT 0${Math.max(index, 0) + 1} · ${escapeHTML(study.game)}</p>${badge(study.status)}</div><h2 id="case-dialog-title">${escapeHTML(study.title)}</h2><p class="case-summary">${escapeHTML(study.summary)}</p><p class="case-question"><strong>핵심 질문</strong>${escapeHTML(study.question)}</p><div class="review-route" aria-label="권장 검토 순서"><strong>권장 검토 순서</strong>${reviewRoute.map((item, i) => `${i ? '<i>→</i>' : ''}<span>${escapeHTML(item)}</span>`).join('')}</div>${executiveSummary}${finalDecision}${selectedActionOutput}${benchmarks}${actionOptions}${researchDetails}${actionDetails}${interviewPitch}${supportingDetails}</div>`;
  dialog.querySelector('.dialog-close').addEventListener('click', () => dialog.close());
  dialog.scrollTop = 0;
  document.body.classList.add('dialog-open');
  if (typeof dialog.showModal === 'function') dialog.showModal(); else dialog.setAttribute('open', '');
}

document.addEventListener('click', (event) => {
  const trigger = event.target.closest('[data-open-case]');
  if (trigger) { lastCaseTrigger = trigger; openCase(trigger.dataset.openCase); }
  if (event.target === dialog) dialog.close();
});
dialog.addEventListener('close', () => {
  document.body.classList.remove('dialog-open');
  if (lastCaseTrigger?.isConnected) lastCaseTrigger.focus();
});

function renderProcess(selector, steps) {
  document.querySelector(selector).innerHTML = steps.map((step, i) => `<article class="process-step"><span class="eyebrow">${String(i + 1).padStart(2, '0')}</span><h3>${escapeHTML(step.title)}</h3><p>${escapeHTML(step.text)}</p></article>`).join('');
}
renderProcess('#service-process', data.serviceSteps);
renderProcess('#ai-process', data.aiSteps);
const primaryTopics = data.dataAnalysis.topics.slice(0, 4);
const additionalTopics = data.dataAnalysis.topics.slice(4);
document.querySelector('#data-topics').innerHTML = `${tags(primaryTopics)}${additionalTopics.length ? `<details class="topic-more"><summary>근거 항목 ${additionalTopics.length}개 더 보기</summary><div class="tags">${tags(additionalTopics)}</div></details>` : ''}`;
document.querySelector('#data-evidence').innerHTML = data.dataAnalysis.images.map((item) => assetURL(item.src) ? `<figure><img src="${escapeHTML(assetURL(item.src))}" alt="${escapeHTML(item.alt)}" loading="lazy"><figcaption>${escapeHTML(item.caption || '')}</figcaption></figure>` : '').join('') + artifactLinks(data.dataAnalysis.documents);
document.querySelector('#skills-grid').innerHTML = data.skills.map((skill, index) => `<article class="skill-card"><span class="skill-number">0${index + 1}</span><h3>${escapeHTML(skill.title)}</h3><p>${escapeHTML(skill.subtitle)}</p><div class="tags">${tags(skill.items)}</div></article>`).join('');

document.querySelector('#contact-links').innerHTML = data.contacts.map((contact) => {
  const safeURL = /^(https:\/\/|mailto:|tel:)/i.test(contact.url) ? contact.url : '';
  const content = `<span class="contact-label">${escapeHTML(contact.label)}</span><span>${escapeHTML(contact.text)} <span aria-hidden="true">↗</span></span>`;
  return safeURL ? `<a href="${escapeHTML(safeURL)}"${safeURL.startsWith('https:') ? ' target="_blank" rel="noopener noreferrer"' : ''}>${content}</a>` : `<span class="contact-placeholder">${content}</span>`;
}).join('');
document.querySelector('#year').textContent = new Date().getFullYear();

const toggle = document.querySelector('.menu-toggle');
const nav = document.querySelector('#navigation');
function closeMenu() { toggle.setAttribute('aria-expanded', 'false'); nav.classList.remove('is-open'); }
toggle.addEventListener('click', () => { const open = toggle.getAttribute('aria-expanded') !== 'true'; toggle.setAttribute('aria-expanded', String(open)); nav.classList.toggle('is-open', open); });
nav.addEventListener('click', (event) => { if (event.target.closest('a')) closeMenu(); });
document.addEventListener('keydown', (event) => { if (event.key === 'Escape' && toggle.getAttribute('aria-expanded') === 'true') { closeMenu(); toggle.focus(); } });
document.addEventListener('click', (event) => { if (!event.target.closest('.nav-shell')) closeMenu(); });
window.matchMedia('(max-width: 900px)').addEventListener('change', closeMenu);

if ('IntersectionObserver' in window) {
  const sections = document.querySelectorAll('main section[id]');
  const navLinks = [...nav.querySelectorAll('a')];
  const activeObserver = new IntersectionObserver((entries) => entries.forEach((entry) => { if (entry.isIntersecting) navLinks.forEach((link) => { const active = link.hash === `#${entry.target.id}`; link.classList.toggle('active', active); if (active) link.setAttribute('aria-current', 'location'); else link.removeAttribute('aria-current'); }); }), { rootMargin: '-18% 0px -65% 0px', threshold: 0 });
  sections.forEach((section) => activeObserver.observe(section));
  if (!window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
    const reveal = new IntersectionObserver((entries) => entries.forEach((entry) => { if (entry.isIntersecting) { entry.target.classList.add('revealed'); reveal.unobserve(entry.target); } }), { threshold: 0.08 });
    document.querySelectorAll('.section-heading, .core-card, .case-card, .skill-card').forEach((el) => { el.classList.add('reveal'); reveal.observe(el); });
  }
}
